css:
/* Chrysaki tri-primary sweep under the chat header. */
[data-chat-header] { border-bottom: 1px solid transparent; border-image: linear-gradient(90deg, #1a8a6a, #1c3d7a, #583090) 1; }
/* Jewel glow on the focused composer card. */
[data-slot="composer-host"]:focus-within { border-color: #583090 !important; box-shadow: 0 0 0 1px #583090, 0 0 18px -6px #1a8a6a; }
/* Amethyst edge on the selected thread row. */
[data-thread-item][aria-current], [data-thread-item][data-active="true"] { box-shadow: inset 2px 0 0 #583090; }
::-webkit-scrollbar-thumb { background: #363a4f; border-radius: 0; }
::-webkit-scrollbar-thumb:hover { background: #62758a; }
[data-slot="scroll-area-thumb"] { background: #363a4f !important; }
.chat-markdown-codeblock { border: 1px solid #252836; }
/* Usage rows in the thread details card. The app shows the percent that remains, so the value says so. */
[data-thread-details-card] [aria-label$="% left"] > span:last-child::after { content: " left"; font-weight: 400; color: #a0a4b8; }
/* A thicker bar on a Raised track. */
[data-thread-details-card] [aria-label$="% left"] > span:nth-child(2), [data-thread-details-card] [aria-label^="Context:"] > span:nth-child(2) { height: 5px; background: #252836 !important; }
/* Emerald to teal for a limit, amethyst for the context. The warning and error colours of the app stay. */
[data-thread-details-card] [aria-label$="% left"] > span:nth-child(2) > span:first-child:not([class*="bg-warning"]):not([class*="bg-error"]) { background: linear-gradient(90deg, #1a8a6a, #20969c) !important; }
[data-thread-details-card] [aria-label^="Context:"] > span:nth-child(2) > span:first-child:not([class*="bg-warning"]):not([class*="bg-error"]) { background: linear-gradient(90deg, #583090, #3d95e0) !important; }
